import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.BN3Eol-0.js";const u=JSON.parse('{"title":"UXS-001 — Solar System Explorer","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/UXS-001.md","filePath":"uxs/UXS-001.md"}'),s={name:"uxs/UXS-001.md"};function r(i,e,l,d,c,h){return t(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="uxs-001-—-solar-system-explorer" tabindex="-1">UXS-001 — Solar System Explorer <a class="header-anchor" href="#uxs-001-—-solar-system-explorer" aria-label="Permalink to &quot;UXS-001 — Solar System Explorer&quot;">​</a></h1><blockquote><p>Status · Draft v0.1 Visual fidelity · Verified against prototype (P01_solar-system-explorer.html) IA anchor · §surfaces/explore · §topbar-patterns · §shared-tokens Related PRD · PRD-001 Related ADRs · ADR-001 (Three.js r128), ADR-011 (TypeScript), ADR-012 (SvelteKit) Related RFCs · RFC-001 (routing)</p></blockquote><h2 id="why-this-uxs-exists" tabindex="-1">Why this UXS exists <a class="header-anchor" href="#why-this-uxs-exists" aria-label="Permalink to &quot;Why this UXS exists&quot;">​</a></h2><p>The solar system explorer renders to both Three.js (3D mode) and Canvas 2D (2D mode). This UXS defines the static appearance contract for both modes, the detail panel tabs, and the planet-specific visual treatments.</p><h2 id="principles" tabindex="-1">Principles <a class="header-anchor" href="#principles" aria-label="Permalink to &quot;Principles&quot;">​</a></h2><ul><li>The solar system is immediately recognisable — Saturn&#39;s rings, Jupiter&#39;s bands, Earth&#39;s blue</li><li>Selected bodies are unambiguous without obscuring their neighbours</li><li>The TECHNICAL tab shows data, not decoration — Space Mono throughout</li><li>The tooltip appears close to the body without overlapping the label</li><li>2D orbit rings are subtle; planets are the signal</li></ul><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>In scope: nav bar, 3D scene layout, 2D canvas layout, planet sphere gradients, selection ring, detail panel (all four tabs), floating tooltip, speed controls, bottom bar. Non-goals: animation timing, hover state transitions, zoom gesture handling. Boundary note: interaction behaviour (click detection logic, zoom formula, drag-to-pan) belongs in the screen module, not here.</p><h2 id="theme" tabindex="-1">Theme <a class="header-anchor" href="#theme" aria-label="Permalink to &quot;Theme&quot;">​</a></h2><p>Dark only. Background <code>#04040c</code> always.</p><h2 id="tokens" tabindex="-1">Tokens <a class="header-anchor" href="#tokens" aria-label="Permalink to &quot;Tokens&quot;">​</a></h2><h3 id="inherited-from-ia" tabindex="-1">Inherited from IA <a class="header-anchor" href="#inherited-from-ia" aria-label="Permalink to &quot;Inherited from IA&quot;">​</a></h3><p>All shared colour tokens, typography tokens, spacing tokens, nav bar spec.</p><h3 id="defined-here" tabindex="-1">Defined here <a class="header-anchor" href="#defined-here" aria-label="Permalink to &quot;Defined here&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>planet-mercury: #c8c8c8 / gradient: #d0c8c0 → #504840</span></span>
<span class="line"><span>planet-venus:   #e8cda0 / gradient: #f0e0a0 → #9a7820</span></span>
<span class="line"><span>planet-earth:   #4b9cd3 / gradient: #6ab8e8 → #0d3050</span></span>
<span class="line"><span>planet-mars:    #c1440e / gradient: #e0704a → #7a2000</span></span>
<span class="line"><span>planet-jupiter: #c88b3a / gradient: #deb878 → #6a3a0e</span></span>
<span class="line"><span>planet-saturn:  #e4d191 / gradient: #ece8b0 → #9a8830</span></span>
<span class="line"><span>planet-uranus:  #7de8e8 / gradient: #a8f0f0 → #207878</span></span>
<span class="line"><span>planet-neptune: #4466bb / gradient: #6080d8 → #101858</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sun-core:       #fff8e7</span></span>
<span class="line"><span>sun-glow-inner: rgba(255,228,130,0.9) at r=0, transparent at r=90px</span></span>
<span class="line"><span>orbit-ring:     rgba(255,255,255,0.05) unselected, rgba(80,112,255,0.3) selected</span></span>
<span class="line"><span>kuiper-belt:    rgba(140,160,210,0.035–0.05) per particle</span></span>
<span class="line"><span>planet-nine:    rgba(160,120,220,0.14) ring, rgba(160,120,220,0.32) label</span></span></code></pre></div><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><h3 id="_3d-mode" tabindex="-1">3D mode <a class="header-anchor" href="#_3d-mode" aria-label="Permalink to &quot;3D mode&quot;">​</a></h3><p>Full viewport Three.js canvas. Nav bar overlaid at top. Planet label divs positioned by 3D projection. Detail panel slides in from right (400px wide). Speed controls and bottom bar at bottom.</p><h3 id="_2d-mode" tabindex="-1">2D mode <a class="header-anchor" href="#_2d-mode" aria-label="Permalink to &quot;2D mode&quot;">​</a></h3><p>Full viewport Canvas 2D. Solar system centre at canvas centre (transform: translate(W/2+panX, H/2+panY) scale(zoom)). Stars drawn in screen space before transform. All orbital objects drawn in world space. Detail panel same as 3D mode.</p><h3 id="detail-panel-tabs" tabindex="-1">Detail panel tabs <a class="header-anchor" href="#detail-panel-tabs" aria-label="Permalink to &quot;Detail panel tabs&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────┐</span></span>
<span class="line"><span>│  TYPE · AGENCY            [←][×] │  fixed header, line 1: badges + × at the badges&#39; 24 px</span></span>
<span class="line"><span>│  PLANET NAME                     │  line 2: the name, full width</span></span>
<span class="line"><span>├──────────────────────────────────┤</span></span>
<span class="line"><span>│  key stats                       │</span></span>
<span class="line"><span>│  [GO TO MARS] [PLAN] [SHARE]     │  action row, at most 3 chips + Share</span></span>
<span class="line"><span>│  hero (planets: whole disc)      │</span></span>
<span class="line"><span>│  OVERVIEW │ TECHNICAL │ LEARN │ SIZES │</span></span>
<span class="line"><span>├──────────────────────────────────┤</span></span>
<span class="line"><span>│  Tab content (scrollable)        │</span></span>
<span class="line"><span>└─────────────────────────────────┘</span></span></code></pre></div><p>The header is one fixed block above the scroll container (eyebrow and actions on line 1, the name at full width on line 2, <a href="./decisions/UXD-018-panel-shell-and-actions">UXD-018</a> amended); Share shows when the entity has a collectible card; the action row holds the entity&#39;s actions and nothing is stacked at the foot (<a href="./decisions/UXD-018-panel-shell-and-actions">UXD-018</a>). The &quot;view&quot; chip of Earth, Mars, Venus (planet panel) and the Moon (satellite panel) is &quot;Go to Mars&quot; (and so on), a link to the world page (<code>WorldLinkChip</code>, one table <code>world-links.ts</code>, <a href="./decisions/UXD-028-explore-and-worlds-link-both-ways">UXD-028</a>); every other body has none. The science block (the cards under the editorial text, or the SCIENCE tab on a mission) lists at most five <code>/science</code> sections, through <code>pickScienceLinks</code> (<a href="./decisions/UXD-022-science-link-lists">UXD-022</a>): curated per body, ranked per mission class and defining phase, no default list (a body with none shows no block); an Earth object and a station module show theirs as compact cards (title and intro). The block is the last item of OVERVIEW and never counts the action row. Tab strip: 11px Space Mono, letter-spacing 2px. Active tab: white, 2px solid <code>var(--color-accent)</code> (<code>#5070ff</code>) bottom border. Inactive: <code>rgba(255,255,255,0.35)</code>.</p><p><strong>Star, outer-scale and black-hole panels</strong> (<code>UniversePanelBody</code>, <a href="./decisions/UXD-023-star-and-outer-panels-follow-the-planet-pattern">UXD-023</a>, extends <a href="./decisions/UXD-008-star-panel-one-hero-and-in-the-sky-tab">UXD-008</a>) are the same skeleton: header, action row, ONE hero, tab row, Overview. One hero at most and <strong>no hero, no slot</strong> (no empty frame): an image (16:9 cover, opens the lightbox; a photo of a part of the entity says what is pictured), else a star&#39;s drawn portrait, else nothing. Tabs: OVERVIEW; GALLERY second and only with two or more images; the panel&#39;s own tabs after; one tab draws no tab row. A star&#39;s tabs are OVERVIEW · GALLERY · <strong>IN THE SKY</strong> · SYSTEM · TECHNICAL: IN THE SKY holds the constellation finder, the constellation named, a zodiac note for the thirteen ecliptic constellations and the action &quot;Show constellation lines&quot;. <strong>A deep-sky object&#39;s tabs are OVERVIEW · IN THE SKY</strong> (<a href="./decisions/UXD-049-deep-sky-panel-in-the-sky-tab">UXD-049</a>, L42): the figure of the object&#39;s constellation with the object ringed (a ring, not the star glow), then six cells computed from its own RA / Dec / magnitude and the 62 named stars: CONSTELLATION, POSITION (RA and Dec as numbers), NEAREST BRIGHT STAR (the nearest named star within 15 degrees, drawn on the chart when it fits, the row left out beyond), BEST MONTHS (the run of months in which, from the reader&#39;s latitude, the object stands at least 20 degrees up in astronomical darkness, the Sun more than 18 degrees below the horizon, for four hours a night on average, from the JPL Horizons Sun table with a &quot;JPL Horizons&quot; link under the value; the row is left out when no month qualifies or the time zone is unknown; a full year reads &quot;Jan to Dec&quot;), FROM YOUR LATITUDE (the highest altitude with refraction: high above 60 degrees of altitude, low under 20, never rises at 0 or less, nothing between; the latitude is the browser time zone&#39;s, no permission prompt, the row left out when the zone is unknown) and SEEN WITH (a magnitude rule, naked eye to 6, binoculars to 9, telescope above, the row left out without a magnitude); then the zodiac note and the action. The deep-sky entity pages do not carry it yet. The lead is <code>.editorial</code>, the facts are the planet cell look three per row, no <code>rem</code> font size. A black hole opens its panel in place; its action &quot;See the lensing simulation&quot; enters the takeover. <strong>The entity page shows the same picture</strong> (phase 4 of the galaxy pages, ADR-096 items 17 and 18): the page hero is one <code>EntityHero</code> figure under the lede, drawn from the same loader (a deep-sky object&#39;s own gallery photo, else <code>panel-heroes.json</code>: the LMC, SMC, Triangulum (NGC 604), IC 342 Group, M101 Group, Perseus–Pisces Supercluster), its caption naming a pictured part and the author from the provenance row; no hero, no slot. <strong>A star page</strong> (<code>/explore/stars/&lt;id&gt;</code>) shows its panel photo the same way, with the panel&#39;s reviewed crop from <code>stars-hero-overrides.json</code> (Sirius 50% 35%); seven stars (Sirius, Rigil Kentaurus, Rigel, Betelgeuse, Antares, Fomalhaut, Proxima Centauri) have one; Vega (a labelled JWST disk figure), Altair (a gridded model view) and Barnard&#39;s Star (an unmarked star field) keep the panel image and get no page hero (<code>NO_PAGE_HERO</code> in <code>star-entity.ts</code>).</p><h3 id="bottom-bar" tabindex="-1">Bottom bar <a class="header-anchor" href="#bottom-bar" aria-label="Permalink to &quot;Bottom bar&quot;">​</a></h3><p>Height 68px. Background <code>rgba(4,4,12,0.88)</code>. Speed buttons left. Hint text right.</p><h3 id="index" tabindex="-1">INDEX <a class="header-anchor" href="#index" aria-label="Permalink to &quot;INDEX&quot;">​</a></h3><p>The left-edge INDEX lists every selectable body of the solar system (Sun, planets, dwarfs and small bodies, moons, the two belts), the same rail as the other seven scales (<a href="./UXS-014#the-index-on-every-scale">UXS-014</a>, <a href="./decisions/UXD-017-one-index-on-every-scale">UXD-017</a>, amended by C6). Here each row has two lines: the body&#39;s name over its distance from the Sun, its diameter and, for a planet, its listed moons (<code>1.52 AU · 6,779 km · 2 major moons</code>). The chips are Planets, Dwarfs, Asteroids, Moons and Comets; only the Sun and the two belts are reachable under All alone. In the 296 px rail All, Planets, Dwarfs and Moons are on one line and Asteroids and Comets are behind a FILTERS button beside the count (C6-F; how many fit is measured, so it follows the language). The Sun and each planet keep their own colour, as the ring of the round photo that leads their row (L45-T2, <a href="./decisions/UXD-025-lists-carry-a-round-photo">UXD-025</a>: 40 of the 51 rows have a photo; the 11 small bodies with no image keep the grey dot).</p><h2 id="component-states" tabindex="-1">Component states <a class="header-anchor" href="#component-states" aria-label="Permalink to &quot;Component states&quot;">​</a></h2><p><strong>Planet (unselected):</strong> base sphere gradient, outer glow at 4–5× radius, label at <code>planet_name_color + cc</code><strong>Planet (selected):</strong> pulsing selection ring (r = planet_radius + 10 + sin(frame)*3), bright label white, panel open <strong>Sun (unselected):</strong> radial glow 0–90px, 14px white core, &quot;SUN&quot; label below <strong>Sun (selected):</strong> same + pulsing gold ring (r = 22 + sin(frame)*4, rgba(255,220,80,0.4–0.7)) <strong>Tooltip (visible):</strong> <code>rgba(4,4,16,0.93)</code> bg, <code>rgba(80,112,255,0.4)</code> border, 3 data lines in Space Mono 11px <strong>Tooltip (hidden):</strong> display:none <strong>Speed button (active):</strong> <code>rgba(80,112,255,0.25)</code> bg, <code>rgba(80,112,255,0.5)</code> border, <code>#8aa0ff</code> text <strong>Speed button (inactive):</strong> transparent bg, <code>rgba(255,255,255,0.1)</code> border, <code>rgba(255,255,255,0.35)</code> text</p><h2 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h2><ul><li>Nav bar: see IA §topbar-patterns, RFC-005</li><li>Detail panel: semantic headings, keyboard-closable (Escape)</li><li>Canvas: <code>aria-label=&quot;Interactive solar system. Use the detail panel for screen reader access.&quot;</code></li><li><code>prefers-reduced-motion</code>: stop auto-orbit in 3D, stop simTime advance in 2D</li></ul><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><blockquote><p><strong>As-built note (2026-10-16):</strong> the boxes below were not maintained after implementation and are not a record of what shipped. For shipped behaviour see <a href="./../adr/TA"><code>docs/adr/TA.md</code></a> and <a href="./../../CHANGELOG"><code>CHANGELOG.md</code></a>.</p></blockquote><ul><li>[ ] All 8 planets visible and correctly coloured in both 3D and 2D</li><li>[ ] Saturn&#39;s rings visible in both modes</li><li>[ ] Jupiter&#39;s bands visible in 2D at size ≥ 6px radius</li><li>[ ] Selection ring pulses on selected planet in both modes</li><li>[ ] Tooltip appears within 200ms of selection in 2D, on hover in 3D</li><li>[ ] Tooltip shows velocity, distance, and orbital params (no planet name)</li><li>[ ] TECHNICAL tab shows vis-viva velocity updating as planet moves</li><li>[ ] SIZES tab canvas shows all planets at true relative scale</li><li>[ ] Sun panel opens with TECHNICAL and LEARN tabs</li><li>[ ] 2D zoom anchored to cursor; 2D drag works</li><li>[ ] All nav links work (MOON, EXPLORE active, PLAN, FLY, MISSIONS, EARTH)</li></ul><hr><h2 id="extension-—-gallery-learn-tabs-v0-1-10" tabindex="-1">Extension — GALLERY + LEARN tabs (v0.1.10) <a class="header-anchor" href="#extension-—-gallery-learn-tabs-v0-1-10" aria-label="Permalink to &quot;Extension — GALLERY + LEARN tabs (v0.1.10)&quot;">​</a></h2><p>PlanetPanel and SunPanel gain two new tabs after the existing OVERVIEW / TECHNICAL / SIZES set. Layout, typography, and tokens follow UXS-004 §Extension and the shared <code>src/lib/styles/panel-tabs.css</code>.</p><h3 id="layout-1" tabindex="-1">Layout <a class="header-anchor" href="#layout-1" aria-label="Permalink to &quot;Layout&quot;">​</a></h3><ul><li>Tabs row stays at top of panel; new tabs appear after SIZES (planets) or TECHNICAL (sun).</li><li>Tab condition: GALLERY shown when <code>static/data/planet-galleries.json[id]</code> (or <code>sun-gallery.json</code>) &gt; 0; LEARN shown when overlay has non-empty <code>links[]</code>.</li></ul><h3 id="tokens-extension" tabindex="-1">Tokens (extension) <a class="header-anchor" href="#tokens-extension" aria-label="Permalink to &quot;Tokens (extension)&quot;">​</a></h3><p><strong>GALLERY thumb (planets, default):</strong> <code>border-color rgba(80, 112, 255, 0.6)</code> on hover (accent blue). <strong>GALLERY thumb (sun):</strong> <code>border-color rgba(255, 200, 80, 0.6)</code> on hover (theme-gold override; scoped CSS in SunPanel). <strong>Active tab border (planets):</strong> <code>#5070ff</code> (<code>--color-accent</code>). <strong>Active tab border (sun):</strong> <code>#ffc850</code>.</p><h3 id="acceptance-criteria-extension" tabindex="-1">Acceptance criteria (extension) <a class="header-anchor" href="#acceptance-criteria-extension" aria-label="Permalink to &quot;Acceptance criteria (extension)&quot;">​</a></h3><ul><li>[ ] GALLERY tab renders when planet/sun manifest count &gt; 0; hidden otherwise</li><li>[ ] LEARN tab renders when overlay has links; hidden otherwise</li><li>[ ] Lightbox opens on thumbnail click; closes on click anywhere</li><li>[ ] LEARN tab shows tiered intro/core/deep groupings with the canonical accent colors (muted blue <code>#889fe7</code> / blue / gold)</li></ul>`,44)])])}const b=a(s,[["render",r]]);export{u as __pageData,b as default};
